package dev.studyforge.banking.domain; import java.time.*; import java.util.*; public record Transaction(UUID id,TransactionType type,AccountId source,AccountId destination,Money amount,Money fee,Instant occurredAt){public Transaction{Objects.requireNonNull(id);Objects.requireNonNull(type);Objects.requireNonNull(amount);Objects.requireNonNull(fee);Objects.requireNonNull(occurredAt);if(!amount.isPositive())throw new InvalidBankingOperationException("Transaction amount must be positive");if(fee.amount().signum()<0)throw new InvalidBankingOperationException("Fee must not be negative");if(!amount.currency().equals(fee.currency()))throw new CurrencyMismatchException(amount.currency(),fee.currency());}}
